const SUM_CASES = [
    (3, 29.874291914525198),
    (8, 29.024116634298302),
    (13, 385.47838185823605),
    (100, -63358.74339536097),
    (128, -97559.83901827873),
    (129, -97559.8407643752),
    (300, -63644.985487097925),
]

@testset "pysd_sum: numpy order" begin
    for (n, expected) in SUM_CASES
        @test pysd_sum(SUM_VALUES[i] for i in 1:n) === expected
        @test pysd_sum(SUM_VALUES[1:n]) === expected
    end
    # sequential sums differ in the last digits for these lengths
    @test sum(SUM_VALUES[i] for i in 1:8) != pysd_sum(SUM_VALUES[1:8])
    @test pysd_sum(Float64[]) === 0.0
    # over the first subscript of a 2-D array numpy adds row after row
    @test pysd_sum_seq(SUM_VALUES[i] for i in 1:8) == foldl(+, SUM_VALUES[1:8])
    @test pysd_sum_seq(SUM_VALUES[i] for i in 1:8) != pysd_sum(SUM_VALUES[1:8])
    @test pysd_sum_seq([1.0, NaN, 2.0]) === 3.0
    @test pysd_sum_seq(Float64[]) === 0.0
    @test pysd_sum(x for x in Float64[]) === 0.0
    @test pysd_sum([1.0, NaN, 2.0]) === 3.0                    # as xarray
    @test pysd_sum(i * j for i in 1:2, j in 1:3) == 18
    @test pysd_sum(x for x in SUM_VALUES[1:13] if x > 0) ==
          pysd_sum(filter(>(0), SUM_VALUES[1:13]))
end

@testset "INVERT MATRIX: numpy digits" begin
    m = [4.0 1.0 0.3 2.0; 0.5 3.0 1.1 0.2; 1.7 0.4 5.0 0.9; 0.6 2.2 0.8 6.0]
    expected = [0.26472588594445357 -0.024204893773621818 0.0035155170325557976 -0.08796245974391384;
                -0.011447169418728509 0.3445393026729731 -0.07570162825581288 0.003686323955515666;
                -0.087173642317881 0.003043468809103076 0.20484408433514184 -0.0017701808379477096;
                -0.01065214083186077 -0.12431638411060839 9.316741252356783e-05 0.17434728463576202]
    @test isapprox(pysd_inv_mat2d_elem(m, 2, 3), expected[2, 3]; rtol = 1e-15)
    @test all(isapprox(pysd_inv_mat2d_elem(m, i, j), expected[i, j]; rtol = 1e-15)
              for i in 1:4, j in 1:4)
    batch = permutedims(cat(m, 2m; dims = 3), (3, 1, 2))      # (batch, i, j)
    @test isapprox(pysd_inv_mat3d_elem(batch, 2, 1, 1), expected[1, 1] / 2; rtol = 1e-15)
end

# Cases where Julia's own functions differ from numpy in the last digit
# (numpy 2.4 on Linux, which calls glibc's maths library, as PySD.jl does).
const LIBM_CASES = [
    (pysd_exp, -18.995666427080103, 5.627129250383538e-9),
    (pysd_exp, 0.6127620313743094, 1.845521754672559),
    (pysd_ln, 912.0552334101783, 6.815700551190227),
    (pysd_sin, 0.6130224416856791, 0.575342178051223),
    (pysd_cos, 14.8878187209734, -0.68211551524249),
    (pysd_tan, 11.995181042198134, -0.6426481299471215),
    (pysd_atan, -2.602097910994317, -1.2038926524277114),
    (pysd_sinh, 12.20011694981521, 99406.20042595758),
    (pysd_cosh, -18.600899082988622, 5.987393954729876e7),
    (pysd_asin, -0.6276839870974102, -0.6785745404429159),
    (pysd_acos, -0.7164396155192634, 2.3694817767537173),
]
const POW_CASES = [
    (591.1111787175414, 0.3194888276189074, 7.682761201254199),
    (102.41647707592044, -0.41113401029618046, 0.14909689130240703),
]

@testset "maths functions: numpy digits" begin
    exact = Sys.islinux() && PySD._libm_exp[] != C_NULL
    for (f, x, expected) in LIBM_CASES
        @test exact ? f(x) === expected : isapprox(f(x), expected; rtol = 1e-15)
    end
    for (x, y, expected) in POW_CASES
        @test exact ? pysd_power(x, y) === expected : isapprox(pysd_power(x, y), expected; rtol = 1e-15)
    end
    @test exp(0.6127620313743094) != 1.845521754672559 || !exact   # why this is needed
    # out of the domain: NaN, as numpy
    @test isnan(pysd_ln(-1.0)) && isnan(pysd_asin(2.0)) && isnan(pysd_power(-8.0, 1 / 3))
    @test pysd_power(-8.0, 3) === -512.0 && pysd_power(2, 3) === 8.0
    @test pysd_exp(1) === pysd_exp(1.0)
end

@testset "elements a model does not define: NaN" begin
    x = pysd_safe([1.0, 2.0])
    @test x[2] === 2.0 && isnan(x[3])
    @test isnan(pysd_safe(zeros(2, 2))[3, 1])
    @test pysd_safe([1, 2])[3] === 0
end
